124: function ConvertFrom-RunOutput {
125:     param($Out, [int]$Code)
126:     $text = (($Out | ForEach-Object { "$_" }) -join "`n")
127:     $preview = $null
128:     $mark = 'sessions.json entry preview:'
129:     $at = $text.IndexOf($mark)
130:     if ($at -ge 0) { try { $preview = $text.Substring($at + $mark.Length) | ConvertFrom-Json } catch { $preview = $null } }
131:     return [pscustomobject]@{ Code = $Code; Out = $text; Preview = $preview; First = (($text -split "`n") | Select-Object -First 1) }
132: }
